"use client";

import { useEffect, useState } from "react";
import { Wifi, MessageSquare, Radio, Inbox } from "lucide-react";
import { useActiveChannel } from "@/components/ActiveChannelProvider";

type ChannelData = {
  id: string;
  login: string;
  displayName: string;
  profileImageUrl: string | null;
  broadcasterType: string | null;
  channelInfo: any;
  streamInfo: any;
  chatSettings: any;
  permissions: { isBroadcaster: boolean; isMod: boolean; isVIP: boolean };
};

function Section({
  title,
  icon: Icon,
  children,
}: {
  title: string;
  icon?: React.ElementType;
  children: React.ReactNode;
}) {
  return (
    <div className="section-card">
      <div className="section-header">
        {Icon && <Icon size={14} className="text-fg-subtle shrink-0" />}
        <span>{title}</span>
      </div>
      <div className="section-body">{children}</div>
    </div>
  );
}

function InfoRow({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="info-row">
      <span className="text-fg-dim text-sm min-w-[160px] shrink-0">{label}</span>
      <span className="text-fg text-sm flex-1">
        {value ?? <span className="text-fg-subtle">—</span>}
      </span>
    </div>
  );
}

export default function HomePage() {
  const { activeChannelId, loading: channelLoading } = useActiveChannel();
  const [data, setData] = useState<ChannelData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!activeChannelId) return;
    setLoading(true);
    setData(null);
    fetch(`/dashboard/api/channels/${activeChannelId}`)
      .then((r) => (r.ok ? r.json() : null))
      .then(setData)
      .catch(() => {})
      .finally(() => setLoading(false));
  }, [activeChannelId]);

  if (!channelLoading && !activeChannelId) {
    return (
      <div className="max-w-3xl">
        <h1 className="text-fg text-2xl font-bold mb-1">Overview</h1>
        <div className="bg-card border border-line rounded-xl p-10 text-center mt-6">
          <Inbox size={36} className="text-fg-subtle mx-auto mb-3" />
          <p className="text-fg font-semibold mb-1">No channels found</p>
          <p className="text-fg-dim text-sm">
            You don't have any roles in channels connected to this Waiter instance.
          </p>
        </div>
      </div>
    );
  }

  if (loading || !data) {
    return (
      <div className="max-w-3xl">
        <h1 className="text-fg text-2xl font-bold mb-5">Overview</h1>
        <div className="flex flex-col gap-4">
          {[1, 2, 3].map((i) => (
            <div key={i} className="h-28 bg-card border border-line rounded-xl animate-pulse" />
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-3xl flex flex-col gap-5">
      {/* Channel identity header */}
      <div className="flex items-center gap-4">
        {data.profileImageUrl ? (
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src={data.profileImageUrl}
            alt=""
            width={48}
            height={48}
            className="rounded-full border border-line shrink-0"
          />
        ) : (
          <div className="w-12 h-12 rounded-full bg-elevated border border-line flex items-center justify-center shrink-0">
            <Radio size={20} className="text-fg-subtle" />
          </div>
        )}
        <div className="min-w-0">
          <h1 className="text-fg text-xl font-bold leading-none mb-1 truncate">{data.displayName}</h1>
          <p className="text-fg-subtle text-sm">
            @{data.login} · {data.broadcasterType || "viewer"}
          </p>
        </div>
      </div>

      {/* Live now */}
      {data.streamInfo ? (
        <Section title="Live Now" icon={Wifi}>
          <InfoRow label="Title" value={data.streamInfo.title} />
          <InfoRow label="Game" value={data.streamInfo.game_name} />
          <InfoRow label="Viewers" value={data.streamInfo.viewer_count?.toLocaleString()} />
        </Section>
      ) : (
        <div className="rounded-xl border border-line bg-card px-5 py-3 text-sm text-fg-subtle flex items-center gap-2">
          <Wifi size={14} />
          Offline — not currently streaming.
        </div>
      )}

      {/* Channel info */}
      <Section title="Channel Info">
        <InfoRow label="Title" value={data.channelInfo?.title} />
        <InfoRow label="Category" value={data.channelInfo?.game_name} />
        <InfoRow label="Language" value={data.channelInfo?.broadcaster_language?.toUpperCase()} />
      </Section>

      {/* Chat settings */}
      {data.chatSettings && (
        <Section title="Chat Settings" icon={MessageSquare}>
          <InfoRow label="Emote only" value={data.chatSettings.emote_mode ? "On" : "Off"} />
          <InfoRow
            label="Followers only"
            value={data.chatSettings.follower_mode ? `${data.chatSettings.follower_mode_duration}m` : "Off"}
          />
          <InfoRow label="Subscribers only" value={data.chatSettings.subscriber_mode ? "On" : "Off"} />
          <InfoRow
            label="Slow mode"
            value={data.chatSettings.slow_mode ? `${data.chatSettings.slow_mode_wait_time}s` : "Off"}
          />
          <InfoRow label="Unique chat" value={data.chatSettings.unique_chat_mode ? "On" : "Off"} />
        </Section>
      )}
    </div>
  );
}
